// High School course unit (docs/design/COURSES.md, docs/design/COURSE_QUALITY.md): World Geography, Unit 1, Maps and Geospatial Tools.
// World Geography is not AP. It follows Geography for Life: National Geography Standards (2nd ed., 2012), and this unit covers the
// first three, "The World in Spatial Terms": NGS 1 (maps, geospatial technologies, spatial thinking), NGS 2 (mental maps) and NGS 3
// (the spatial organization of people, places and environments). Our own wording and questions, nothing copied.
// It is hands-on and complements AP Human Geography Unit 1, which treats map types and projections: here students read latitude and
// longitude, convert degrees and minutes, compute distance from latitude (one degree of latitude is about 111 km; a degree of
// longitude shrinks with the cosine of the latitude), use a map scale written as a ratio, in words or as a bar, work out time
// differences (the Earth turns 15 degrees of longitude per hour; real zones follow political borders, some use half-hour offsets, and
// daylight saving changes a place's offset but never UTC), tell absolute from relative location, read contour lines (interval, relief,
// interpolation, steepness, gradient and percent grade), use compass bearings (clockwise from north, back bearings, magnetic
// declination), see how GPS finds a position from signal travel times (trilateration), how a GIS stacks layers of points, lines and
// polygons, how remote sensing records Earth from a distance (pixels, passive and active sensors), how mental maps work (Kevin Lynch's
// paths, edges, districts, nodes and landmarks), and how to describe density, patterns, connectivity and accessibility.
// Every place used in a calculation is fictional and labelled so; the speed of a GPS signal is rounded to 300,000 km/s as the
// questions say. The unit test recomputes every number and re-derives every lettered answer from a rule table written separately.
const tab=(title,rows,cols=['Value'])=>({t:'setups',title,head:'',rows,cols});
/* Lesson figures use 640 x 280 screen positions (y down), converted to the figure renderer's upward y axis.
   Labels stay inside the 44..596 x 56..248 drawing window; shapes reveal in order. */
const scene=(title,draw)=>{const pts={},polys=[],segs=[],circles=[],notes=[];let i=0;const point=(x,y)=>{const k='P'+i++;pts[k]=[x,280-y];return k;};
 const pen={box:(x,y,w,h,col=0,lw)=>{const v=[[x,y],[x+w,y],[x+w,y+h],[x,y+h]].map(([a,b])=>point(a,b)).join('');polys.push(lw?{v,col,w:lw}:{v,col});},
  poly:(list,col=0,lw)=>{const v=list.map(([a,b])=>point(a,b)).join('');polys.push(lw?{v,col,w:lw}:{v,col});},
  line:(x,y,u,v,col=0,arrows=0,dash=false,w=2)=>segs.push({v:point(x,y)+point(u,v),col,arrows,dash,w}),
  circle:(x,y,r,col=0,dash=false)=>circles.push({c:point(x,y),r,col,dash}),
  note:(x,y,text,col=0)=>notes.push({at:[x,280-y],text,col}),
  arc:(x,y,r,a0,a1,col=0,w=2)=>{const step=a1>=a0?5:-5;for(let a=a0;step>0?a<a1:a>a1;a+=step){const b=step>0?Math.min(a+step,a1):Math.max(a+step,a1),p=t=>[x+r*Math.sin(t*Math.PI/180),y-r*Math.cos(t*Math.PI/180)];segs.push({v:point(...p(a))+point(...p(b)),col,arrows:0,dash:false,w});}}};
 draw(pen);return {t:'figure',title,view:[44,596,32,224],pts,hide:Object.keys(pts).join(''),dots:'',polys,segs,circles,notes};};
const board=(title,lines)=>({t:'board',title,lines,box:true});
const n=v=>v.toLocaleString('en-US');
const r4=v=>Math.round(v*1e4)/1e4;
const ellipse=(cx,cy,rx,ry,k=36)=>Array.from({length:k},(_,i)=>[cx+rx*Math.cos(2*Math.PI*i/k),cy+ry*Math.sin(2*Math.PI*i/k)]);
/* Step pictures */
const gridMap=()=>scene('Reading a grid: Port Karn at 15° N, 25° E (fictional)',d=>{const X=lo=>110+lo*9,Y=la=>222-la*5;
 for(const la of [0,10,20,30]){d.line(X(0),Y(la),X(40),Y(la),la?0:1,0,false,la?1:3);d.note(84,Y(la),la?`${la}° N`:'0°',la?0:1);}
 for(const lo of [0,10,20,30,40]){d.line(X(lo),Y(0),X(lo),Y(30),lo?2:1,0,false,lo?1:3);d.note(X(lo),238,lo?`${lo}° E`:'0°',lo?2:1);}
 d.poly([[21,12],[24,11],[29,13],[30,17],[26,19],[22,17]].map(([lo,la])=>[X(lo),Y(la)]),2);
 d.line(X(25),Y(15),X(25),Y(0),4,0,true,1);d.line(X(25),Y(15),X(0),Y(15),4,0,true,1);d.circle(X(25),Y(15),4,4);
 d.note(X(34),Y(15),'Port Karn',4);d.note(160,62,'Prime meridian',1);d.note(512,Y(0),'Equator',1);
 d.note(538,84,'Latitude first,',0);d.note(538,100,'then longitude',2);d.note(538,138,'12° 45′ N: minutes',1);d.note(538,154,'45 ÷ 60 = 0.75',1);d.note(538,170,'= 12.75° N',1);d.note(538,198,'South, west: negative',4);});
const lengthsFig=()=>scene('Degrees of latitude stay equal; degrees of longitude shrink',d=>{const Y=la=>210-la*3.5;
 d.line(110,Y(0),110,Y(40),0,0,false,3);for(const la of [0,10,20,30,40]){d.line(100,Y(la),120,Y(la),0,0,false,2);d.note(66,Y(la),la?`${la}° N`:'0°',0);}
 for(const la of [5,15,25,35])d.note(180,Y(la),'1,110 km',1);d.note(130,62,'Latitude: equal steps',0);
 d.box(360,110,88.8,30,2);d.box(360,170,44.4,30,3);d.note(404,96,'1° of longitude at the equator',2);d.note(500,125,'111 km',2);d.note(404,156,'at 60° N',3);d.note(470,185,'55.5 km',3);d.note(480,62,'Longitude: narrows poleward',3);});
const scaleFig=()=>scene('One scale written three ways (fictional map)',d=>{
 d.note(110,92,'Ratio',0);d.note(330,92,'1 : 100,000',1);d.note(110,140,'Words',0);d.note(330,140,'1 cm represents 1 km',1);
 d.note(110,196,'Bar',0);for(let k=0;k<3;k++){d.box(250+k*40,184,40,10,k%2?3:1);}
 for(let k=0;k<=3;k++){d.line(250+k*40,184,250+k*40,200,0,0,false,1);d.note(250+k*40,212,String(k),0);}d.note(395,212,'km',0);
 d.note(330,244,'Enlarge the page: the bar grows with it; the ratio no longer fits',2);});
const zonesFig=()=>scene('The Earth turns 15° each hour: 24 nominal zones',d=>{
 for(let k=0;k<24;k++)d.box(80+k*20,118,20,32,k%2?0:1,1);
 for(const [lon,lab] of [[-180,'180° W'],[-90,'90° W'],[0,'0°'],[90,'90° E'],[180,'180° E']]){const x=80+(lon+180)*480/360;d.note(x,166,lab,2);}
 for(const [x,lab] of [[200,'UTC-6'],[320,'UTC+0'],[440,'UTC+6']])d.note(x,104,lab,1);
 d.line(520,80,120,80,3,1,false,2);d.note(320,66,'The sun appears to move west',3);d.note(320,206,'15° of longitude = 1 hour',0);d.note(320,232,'Real zone borders follow countries and regions',2);});
const townFig=()=>scene('Two ways to say where the school is (fictional town)',d=>{
 for(const [x,nm] of [[150,'Elm'],[250,'Oak'],[350,'Pine'],[450,'Cedar']]){d.line(x,88,x,205,0,0,false,2);d.note(x,218,nm,0);}
 for(const [y,nm] of [[100,'1st Ave'],[160,'2nd Ave']]){d.line(130,y,470,y,0,0,false,2);d.note(520,y,nm,0);}
 d.box(160,108,82,44,2);d.note(201,130,'Library',2);d.box(258,108,82,44,1);d.note(299,130,'School',1);
 d.note(320,70,'Relative: one block east of the library',2);d.note(320,240,'Absolute: 120 Oak Street (a fictional address)',1);});
const hillFig=()=>scene('Contour lines of a fictional hill (interval 20 m)',d=>{
 for(let i=0;i<5;i++){d.poly(ellipse(230+14*i,150,150-28*i,84-15*i),i%2?0:1,i===0||i===4?2:2);}
 for(let i=0;i<5;i++)d.note(230+14*i,150-(84-15*i),`${100+20*i} m`,i%2?0:1);
 d.circle(286,152,3,4);d.note(286,166,'187 m',4);
 d.note(512,72,'Interval: 20 m',2);d.note(512,100,'East side:',0);d.note(512,116,'close = steep',0);d.note(512,170,'West side:',0);d.note(512,186,'far apart = gentle',0);});
const slopeFig=()=>scene('Gradient = rise ÷ run (fictional hill)',d=>{
 d.poly([[110,200],[460,100],[460,200]],2,2);d.line(110,200,460,200,0,0,true,1);d.line(460,200,460,100,1,0,true,1);
 d.note(285,218,'run = 2 km',0);d.note(520,150,'rise = 80 m',1);d.note(84,214,'120 m',0);d.note(520,92,'200 m',0);
 d.note(215,82,'Gradient = 80 m ÷ 2 km',4);d.note(215,100,'= 40 m per km',4);});
const compassFig=()=>scene('Bearings run clockwise from north',d=>{
 d.circle(210,150,80,0);for(const [x,y] of [[210,70],[290,150],[210,230],[130,150]])d.line(210,150,x,y,0,0,false,1);
 d.note(210,57,'N 0°',0);d.note(325,150,'E 90°',0);d.note(210,245,'S 180°',0);d.note(98,150,'W 270°',0);
 d.line(210,150,210+80*Math.sin(Math.PI*3/4),150-80*Math.cos(Math.PI*3/4),4,1,false,3);d.arc(210,150,36,0,135,4,2);
 d.line(210,150,210+80*Math.sin(Math.PI*7/4),150-80*Math.cos(Math.PI*7/4),3,1,true,2);d.note(150,82,'315°',3);d.note(280,196,'135°',4);
 d.note(480,92,'Bearing: the angle',0);d.note(480,110,'clockwise from north',0);d.note(480,146,'Back bearing:',3);d.note(480,164,'add or subtract 180°',3);
 d.note(480,200,'135° + 180° = 315°',3);});
const gpsFig=()=>{const R=[320,160],B=[[250,170,'A'],[350,100,'B'],[395,185,'C']];return scene('Trilateration: distances from three known points',d=>{
 B.forEach(([x,y,nm],k)=>{d.circle(x,y,Math.hypot(R[0]-x,R[1]-y),k,true);d.box(x-4,y-4,8,8,k);d.note(x,y-14,nm,k);});
 d.circle(R[0],R[1],5,4);d.note(R[0]+22,R[1]+14,'You',4);
 d.note(108,92,'1 distance:',0);d.note(108,108,'a ring',0);d.note(108,148,'2 distances:',0);d.note(108,164,'two points',0);d.note(108,204,'3 distances:',0);d.note(108,220,'one point',0);
 d.note(536,110,'Fourth signal:',2);d.note(536,126,'fixes the',2);d.note(536,142,'receiver clock',2);});};
const layersFig=()=>scene('A GIS stacks layers that share one set of coordinates',d=>{
 d.box(70,176,200,58,0);d.poly([[90,230],[130,196],[200,186],[250,200],[260,230]],0,1);
 d.box(95,130,200,58,2);d.line(100,176,160,142,2,0,false,3);d.line(160,142,210,168,2,0,false,3);d.line(210,168,290,136,2,0,false,3);
 d.box(120,84,200,58,1);for(const [x,y] of [[160,110],[220,126],[290,100]])d.circle(x,y,4,1);
 d.note(430,106,'Schools: points',1);d.note(430,158,'Roads: lines',2);d.note(430,210,'Flood zone: polygon',0);
 d.note(536,66,'Overlay shows',4);d.note(536,82,'which school floods',4);});
const pixelsFig=()=>{const lake=(u,v)=>Math.hypot(u-0.45,v-0.55)<0.3;return scene('Same ground, two spatial resolutions (fictional)',d=>{
 for(const [x0,k] of [[90,5],[385,10]]){const w=140/k;for(let i=0;i<k;i++)for(let j=0;j<k;j++)d.box(x0+i*w,66+j*w,w,w,lake((i+.5)/k,(j+.5)/k)?0:2,1);}
 d.line(244,136,370,136,1,1,false,2);d.note(307,118,'Smaller pixels,',1);d.note(307,154,'finer detail',1);
 d.note(160,228,'30 m pixels',0);d.note(160,244,'frame 150 m across',0);d.note(455,228,'15 m pixels',0);d.note(455,244,'same frame',0);});};
const mentalFig=()=>scene('The same town: real layout and a mental map',d=>{
 d.box(70,70,200,146,0,1);d.line(170,70,170,216,3,0,false,3);d.line(70,143,270,143,0,0,false,1);
 d.note(120,106,'Home',2);d.note(220,106,'North',0);d.note(120,180,'East',0);d.note(220,180,'West',0);
 d.box(360,70,220,146,0,1);d.box(372,82,110,70,2,2);d.note(427,100,'district',2);d.line(500,70,500,216,3,0,false,3);d.note(540,92,'edge',3);
 d.line(372,184,500,184,1,0,false,3);d.note(396,200,'path',1);d.circle(440,184,8,4);d.note(440,166,'node',4);
 d.poly([[540,150],[552,128],[564,150]],1,2);d.note(540,166,'landmark',1);d.box(522,184,40,22,0,1);d.note(542,198,'far',0);
 d.note(170,236,'Real layout: equal districts',0);d.note(470,236,'Mental map: home looms large',3);});
const netFig=()=>scene('Connectivity: the same four towns, two road networks (fictional)',d=>{
 const A=[[80,200],[140,110],[200,200],[260,110]],B=[[380,110],[540,110],[380,200],[540,200]];
 for(const [p,q] of [[0,1],[1,2],[2,3]])d.line(...A[p],...A[q],0,0,false,3);
 for(const [p,q] of [[0,1],[0,2],[0,3],[1,2],[1,3],[2,3]])d.line(...B[p],...B[q],2,0,false,3);
 for(const [x,y] of [...A,...B])d.circle(x,y,6,4);
 d.note(170,236,'Links: 3',0);d.note(460,236,'Links: 6 = 4 × 3 ÷ 2',2);d.note(170,66,'Chain',0);d.note(460,66,'Every pair linked',2);});
const chooseFig=()=>scene('Which tool answers which question',d=>{
 const cells=[['Where exactly?','coordinates, GPS',0],['How far?','scale or degrees',1],['What time?','UTC offsets',2],['How high, how steep?','contours, gradient',3],['What lies where?','GIS layers, imagery',0],['How do people see it?','mental maps',1]];
 cells.forEach(([q,t,c],k)=>{const x=60+(k%3)*175,y=76+Math.floor(k/3)*84;d.box(x,y,160,64,c);d.note(x+80,y+22,q,c);d.note(x+80,y+44,t,c);});
 d.note(320,238,'Check units, signs and the date before you trust a number',4);});
const twoContours=(lo,hi,frac)=>scene('Between two contour lines (fictional)',d=>{
 d.line(100,100,540,100,1,0,false,3);d.line(100,200,540,200,0,0,false,3);d.note(80,100,`${hi} m`,1);d.note(80,200,`${lo} m`,0);
 d.circle(320,200-100*frac,5,4);d.note(380,200-100*frac,'spot: ? m',4);d.line(320,200,320,200-100*frac,4,0,true,1);});
const bearingPic=(dx,dy)=>{const s=Math.min(11,95/Math.max(Math.abs(dx),Math.abs(dy)));return scene('Grid map: A at the center, B somewhere else',d=>{
 d.circle(320,152,5,0);d.note(320,170,'A',0);d.circle(320+dx*s,152-dy*s,5,4);d.note(320+dx*s,152-dy*s-14,'B',4);d.line(320,152,320+dx*s,152-dy*s,4,1,false,2);
 d.line(120,200,120,150,0,1,false,2);d.note(120,138,'N',0);d.note(500,236,'scale not marked: use the numbers',2);});};
/* The Try-it questions in pool form; the generator skips them. */
const TRY=['Two fictional harbors lie on one meridian, at 18° N and 7° N. At 111 km per degree of latitude, how many kilometers apart are they?',
 'A fictional coastal map is drawn at 1 : 200,000. A bay measures 3.5 centimeters across on the map. How many kilometers is that on the ground?',
 'Fictional Alder Port keeps UTC-3 and Vale Town keeps UTC+4. When it is 10:00 in Alder Port, what hour is it in Vale Town on the 24-hour clock?',
 'A hiker leaves camp on a bearing of 300°. What is the bearing for the walk straight back to camp?',
 'A fictional GPS signal takes 0.072 seconds to reach a receiver. Using 300,000 km/s, how many kilometers away is the satellite?'];
const tryIt=s=>`Try it: ${s[0].toLowerCase()+s.slice(1)}`;
/* lettered choices, the right one moved to position k */
const choose=(right,wrong,k)=>{const o=[...wrong];o.splice(k%3,0,right);return {text:o.map((x,i)=>`${'ABC'[i]}: ${x}`).join(', '),letter:'ABC'[o.indexOf(right)]};};
export default {
id:'geography-h-world-geography-maps-and-geospatial-tools',subject:'geography',level:5,grade:9,standard:'National Geography Standards (Geography for Life, 2nd ed., 2012): Standards 1-3, The World in Spatial Terms',
title:'Maps and geospatial tools',
goal:'Read latitude and longitude, compute distances from degrees and from map scale, work out time differences, tell absolute from relative location, read contours and gradients, use compass bearings, explain how GPS, GIS and remote sensing work, describe mental maps, and describe the spatial organization of places.',
points:20,
skills:{latlon:'Latitude and longitude',dist:'Distance from degrees',scale:'Map scale',tz:'Time zones',loc:'Absolute and relative location',contour:'Contour lines and elevation',grad:'Gradient and profiles',bearing:'Compass bearings',gps:'GPS and trilateration',gis:'GIS layers',rs:'Remote sensing',mental:'Mental maps',spatial:'Spatial organization'},
outline:[['NGS 1','How to use maps and other geographic representations, geospatial technologies, and spatial thinking to understand and communicate information',['latlon','dist','scale','tz','loc','contour','grad','bearing','gps','gis','rs']],['NGS 2','How to use mental maps to organize information about people, places, and environments in a spatial context',['mental']],['NGS 3','How to analyze the spatial organization of people, places, and environments on Earth\'s surface',['spatial']]],
steps:[
 {skill:"latlon",say:"Every place has a latitude and a longitude. Latitude counts degrees north or south of the equator, 0° to 90°, along parallels that run east to west. Longitude counts degrees east or west of the prime meridian, 0° to 180°, along meridians that run from pole to pole. Give latitude first, then longitude. A degree is split into 60 minutes, so to use a coordinate in a computer or GPS, divide the minutes by 60; south latitudes and west longitudes become negative numbers.",eq:"decimal degrees = degrees + minutes ÷ 60",pic:gridMap()},
 {skill:"dist",say:"A degree of latitude is almost the same length everywhere, about 111 km (it varies slightly). So the north-south distance between two latitudes on one meridian is the difference in degrees times 111. A degree of longitude is widest at the equator and shrinks toward the poles because meridians meet: it is about 111 × cos(latitude) km, which is half as long at 60° N or S.",eq:"north-south km ≈ degrees of latitude × 111",pic:lengthsFig(),
  check:{prompt:tryIt(TRY[0]),answer:1221,options:[1221,2775,1998],hint:'Subtract the latitudes first: 18 - 7 degrees. Then multiply by 111.',pic:tab('Two harbors',[['latitudes','18° N and 7° N'],['one degree','111 km']])}},
 {skill:"scale",say:"A map scale links distance on paper to distance on the ground. It can be a ratio such as 1 : 100,000, a statement in words such as 1 cm represents 1 km, or a bar marked in kilometers. A bar scale is a drawing, so it stays correct if the map is enlarged or reduced; a ratio then no longer matches the printed page.",pic:scaleFig()},
 {skill:"scale",say:"To find ground distance, measure the map distance, multiply by the scale denominator, then change units. One kilometer is 100,000 centimeters. In this fictional example, 4.5 cm at 1 : 250,000 is 1,125,000 cm, or 11.25 km. To turn the words 1 cm represents 5 km into a ratio, change 5 km to 500,000 cm and write 1 : 500,000.",eq:"ground cm = map cm × denominator",pic:board('Fictional map: from the page to the ground',['Map distance: 4.5 cm; scale 1 : 250,000','Ground = 4.5 × 250,000 = 1,125,000 cm','= 11,250 m = 11.25 km','Words: 1 cm = 5 km → 1 : 500,000']),
  check:{prompt:tryIt(TRY[1]),answer:7,options:[7,70,0.7],hint:'3.5 × 200,000 centimeters; there are 100,000 centimeters in a kilometer.',pic:tab('The map',[['scale','1 : 200,000'],['bay','3.5 cm']])}},
 {skill:"tz",say:"The Earth turns 360° in 24 hours, so the sun appears to cross 15° of longitude each hour. Places east of you have later clock times; places west have earlier. Zones are measured from UTC, the time standard at 0° longitude. A zone about 90° east of the prime meridian is nominally 6 hours ahead of UTC. Real zones follow national and regional borders, so many places differ from this pattern.",eq:"nominal offset in hours = longitude ÷ 15",pic:zonesFig()},
 {skill:"tz",say:"To compare clocks, subtract the offsets and add the result to the local time. In this fictional pair, Harbor City is UTC-5 and Delta Town is UTC+2, so Delta Town is 2 - (-5) = 7 hours ahead. Some places use half-hour offsets, some countries use one zone across a wide area, and daylight saving changes a place's offset (UTC itself never changes). Crossing the date line westward moves you one calendar day ahead.",eq:"other time = local time + (other offset - local offset)",pic:board('Fictional time difference',['Harbor City UTC-5; Delta Town UTC+2','Difference = 2 - (-5) = 7 hours','Harbor City 09:00 → 9 + 7 = 16:00','Delta Town: 16:00 the same day']),
  check:{prompt:tryIt(TRY[2]),answer:17,options:[17,3,13],hint:'Delta is ahead by 4 - (-3) hours. Add that to 10.',pic:tab('Two fictional towns',[['Alder Port','UTC-3'],['Vale Town','UTC+4']])}},
 {skill:"loc",say:"Absolute location is a fixed answer that needs no other place: coordinates or a street address. Relative location describes where something is compared with other places, using direction, distance or travel time, such as one block east of the library. Absolute location of a place does not change, but its relative location can change when a new road or rail line shortens the trip.",pic:townFig()},
 {skill:"contour",say:"A contour line joins points of equal elevation. The contour interval is the elevation step between neighboring lines; the bold index lines are labelled and are spaced several intervals apart. Closed loops that get smaller mark a hill, and the highest loop is the top. Lines that are close together mean a steep slope; lines far apart mean a gentle slope. Lines almost never cross, because one place has one elevation.",pic:hillFig()},
 {skill:"contour",say:"To find the elevation of a spot between two lines, assume an even slope and take the same fraction of the interval. In this fictional example a spot halfway between the 340 m and 360 m lines is at 350 m. Relief is the highest elevation minus the lowest in an area. In a valley, contour lines bend into a V that points uphill, the way the stream comes from; a depression is drawn with short tick marks pointing downslope.",eq:"spot = lower line + fraction × interval",pic:twoContours(340,360,.5),
  check:{prompt:tryIt('A fictional spot lies between the 420 m and 440 m contour lines, one quarter of the way from the 420 m line. Assuming an even slope, what is its elevation in meters?'),answer:425,options:[425,435,430],hint:'One quarter of a 20 m interval is 5 m above the lower line.',pic:twoContours(420,440,.25)}},
 {skill:"grad",say:"Gradient measures steepness as rise over run, with both in the same kind of ground distance. On a map, first convert map distance to ground distance with the scale. In this fictional example the rise is 80 m over a run of 2 km, a gradient of 40 m per km. Percent grade is rise divided by run, times 100, with both in meters: 80 m over 2,000 m is 4%.",eq:"gradient = rise ÷ run",pic:slopeFig()},
 {skill:"bearing",say:"A compass bearing is an angle measured clockwise from north, from 0° up to (but not including) 360°: east is 90°, south 180°, west 270°. The bearing for the return trip, the back bearing, differs by 180°. Magnetic north is not exactly true north; the angle between them is the declination, which varies by place and changes slowly over time, so a compass reading must be corrected for it.",eq:"back bearing = bearing ± 180°",pic:compassFig(),
  check:{prompt:tryIt(TRY[3]),answer:120,options:[120,30,240],hint:'300 + 180 is more than 360, so subtract 180 instead.',pic:tab('The walk',[['outward bearing','300°']])}},
 {skill:"gps",say:"A GPS receiver does not send anything to satellites. It listens to signals that carry the satellite's position and the time sent. The delay times the speed of the signal (about 300,000 km/s, rounded) gives a distance. One distance puts you on a sphere around that satellite, two on a circle where two spheres meet, three on two points, and a fourth signal removes the receiver's clock error. The flat sketch shows the same idea with rings.",eq:"distance = delay × 300,000 km/s",pic:gpsFig(),
  check:{prompt:tryIt(TRY[4]),answer:21600,options:[21600,2160,216000],hint:'Multiply 0.072 by 300,000.',pic:tab('The signal',[['delay','0.072 s'],['speed','300,000 km/s']])}},
 {skill:"gis",say:"A geographic information system, or GIS, stores data as layers that share one coordinate system. Vector layers hold points (a well), lines (a road) and polygons (a lake). Raster layers hold a grid of cells. Overlaying layers answers questions that no single map can, such as which schools sit inside a flood zone. A buffer draws an area at a set distance around a feature, and geocoding turns an address into coordinates.",pic:layersFig()},
 {skill:"rs",say:"Remote sensing records the Earth from aircraft or satellites. The image is a grid of pixels, and the pixel size is its spatial resolution: smaller pixels show finer detail but cover less ground. Passive sensors record light or heat that the surface reflects or gives off; active sensors, such as radar and lidar, send out energy and time the return. Satellites also give repeat views of the same place, which shows change over time.",pic:pixelsFig()},
 {skill:"mental",say:"A mental map is the picture of places that a person carries in mind, built from experience, travel, stories and media. It is personal and not drawn to scale: familiar areas look larger and detailed, distant ones small and vague. Geographers ask people to sketch these maps. Kevin Lynch, studying how people picture cities, found five elements: paths, edges, districts, nodes and landmarks.",pic:mentalFig()},
 {skill:"spatial",say:"The spatial organization of a place is how its people, buildings and routes are arranged. Density is a count per area, such as people per square kilometer. Pattern describes the arrangement: clustered, dispersed or linear. Connectivity is how many links join places; a network of n towns with every pair joined has n × (n - 1) ÷ 2 links. Accessibility depends on travel time and cost, which can differ from straight-line distance.",eq:"links = n × (n - 1) ÷ 2",pic:netFig()},
 {skill:"spatial",summary:true,say:"To use maps well, start with the question and choose the tool: coordinates and GPS for exact position, scale or degrees for distance, offsets for time, contours for height and steepness, GIS and imagery for what lies where, and mental maps for how people see a place. Common mistakes are using 111 km for a degree of longitude away from the equator, reversing the scale, dropping the sign of a southern or western coordinate, and forgetting that real time zones follow borders.",pic:chooseFig()}],
/* an entry course: no earlier unit is required */
progression:{requires:[],operations:2,demand:'Convert degrees and map distances to kilometers, work out time differences and gradients, find bearings, and match a tool, a map feature or a pattern to its definition.'},
items(add){
 const seen=new Set(TRY);
 const put=(skill,prompt,answer,pic,explanation,accept)=>{if(seen.has(prompt))return;seen.add(prompt);add(skill,prompt,answer,pic,explanation,accept);};
 const letters=(skill,title,rows,list,shift=0)=>list.forEach(([q,right,wrong,why],k)=>{const c=choose(right,wrong,k+shift);put(skill,`${q} ${c.text}. Answer A, B or C.`,c.letter,tab(title,rows,['Note']),why||`The answer is ${right}.`,[right]);});
 /* latlon */
 letters('latlon','Latitude and longitude',[['latitude','north-south, from the equator'],['longitude','east-west, from the prime meridian']],[
  ['Lines of latitude, also called parallels, run in which direction?','east to west, parallel to the equator',['north to south, meeting at the poles','from the equator to the prime meridian'],'Parallels of latitude are circles that run east to west around Earth, parallel to the equator. Meridians are the lines that run north to south.'],
  ['What is the latitude of the equator?','0°',['90°','180°'],'The equator is the starting line for latitude, so it is 0°. The poles are at 90° N and 90° S.'],
  ['The prime meridian, 0° longitude, was defined historically through which place?','the Royal Observatory at Greenwich, near London',['the Panama Canal','the geographic North Pole'],'In 1884 an international conference chose the meridian through the Royal Observatory at Greenwich, near London, as 0° longitude.'],
  ['Lines of longitude, also called meridians, all meet where?','at the North and South Poles',['at the equator','at the prime meridian only'],'Meridians run from pole to pole, so they all meet at the North and South Poles. They are farthest apart at the equator.'],
  ['In decimal degrees, what does a negative latitude mean?','the place is south of the equator',['the place is west of the prime meridian','the place is on the equator'],'In decimal degrees, south latitudes are written as negative numbers and north as positive. West longitudes are negative too.']]);
 for(const [la,lo,ans] of [['23° S','150° E','southern-eastern'],['48° N','70° W','northern-western'],['15° S','60° W','southern-western']])
  put('latlon',`A fictional port is at ${la}, ${lo}. In which two hemispheres does it lie: northern-eastern, northern-western, southern-eastern, or southern-western?`,ans,tab('The port',[['latitude',la],['longitude',lo]]),`${la.endsWith('N')?'North':'South'} of the equator and ${lo.endsWith('E')?'east':'west'} of the prime meridian: ${ans}.`,[ans.replace('-',' ')]);
 for(const [d,m] of [[35,30],[48,15],[7,12]])put('latlon',`Write the fictional reading ${d}° ${m}′ N as decimal degrees.`,r4(d+m/60),tab('A reading',[['degrees',`${d}°`],['minutes',`${m}′`]]),`${m} ÷ 60 = ${r4(m/60)}, so ${d}° ${m}′ = ${r4(d+m/60)}°.`);
 put('latlon','A fictional GPS reads 52.75° N. Written as degrees and minutes, how many minutes come after 52°?',45,tab('A reading',[['decimal','52.75° N']]),'0.75° × 60 = 45′.');
 for(const [txt,v] of [['33° S latitude',-33]])put('latlon',`In decimal degrees, with south and west written as negative numbers, what number stands for ${txt}?`,v,tab('Signs',[['rule','south and west are negative']]),`${txt} lies ${txt.includes('S')?'south':'west'}, so the number is negative: ${v}.`);
 /* dist */
 for(const [a,b,sa,sb] of [[12,5,'N','N'],[40,25,'N','N'],[14,9,'N','S'],[6,22,'S','N']]){const same=sa===sb,deg=same?Math.abs(a-b):a+b;
  put('dist',`Two fictional towns lie on the same meridian, one at ${a}° ${sa} and one at ${b}° ${sb}. Using 111 km per degree of latitude, how many kilometers apart are they?`,r4(deg*111),tab('The towns',[['first',`${a}° ${sa}`],['second',`${b}° ${sb}`]]),`${same?`|${a} - ${b}|`:`${a} + ${b}`} = ${deg} degrees; ${deg} × 111 = ${r4(deg*111)} km.`);}
 for(const km of [333,777])put('dist',`A fictional ferry sails due north along a meridian for ${km} km. About how many degrees of latitude does it cover, at 111 km per degree?`,r4(km/111),tab('The voyage',[['distance',`${km} km`]]),`${km} ÷ 111 = ${r4(km/111)} degrees.`);
 for(const dl of [4,7])put('dist',`Two fictional lighthouses sit on the 60° N parallel, ${dl} degrees of longitude apart. At that latitude one degree of longitude is about 55.5 km (111 × 0.5). How many kilometers apart are they?`,r4(dl*55.5),tab('The lighthouses',[['parallel','60° N'],['difference',`${dl}° of longitude`]]),`${dl} × 55.5 = ${r4(dl*55.5)} km.`);
 put('dist','Two fictional villages lie on the equator, 9 degrees of longitude apart. At 111 km per degree, how many kilometers apart are they?',999,tab('The villages',[['on','the equator'],['difference','9° of longitude']]),'9 × 111 = 999 km.');
 put('dist','If one degree of latitude is about 111 km, about how many kilometers is a full circle of 360° around the Earth through both poles?',39960,tab('The circle',[['degrees','360'],['one degree','111 km']]),'360 × 111 = 39,960 km.');
 letters('dist','Degrees and distance',[['1° of latitude','about 111 km'],['1° of longitude','111 km × cos(latitude)']],[
  ['Why is a degree of longitude shorter near the poles than at the equator?','meridians converge toward the poles',['the Earth is flat near the poles','latitude lines get farther apart'],'Meridians converge toward the poles, so the east-west distance between them shrinks with latitude, reaching zero at the poles.'],
  ['At about what latitude is a degree of longitude half as long as at the equator?','60°',['30°','45°'],'The length of a degree of longitude shrinks with the cosine of latitude, and the cosine of 60° is 0.5, so it is half as long there.']],1);
 /* scale */
 for(const [sc,cm] of [[25000,8],[50000,3.4]])put('scale',`A fictional trail map is printed at 1 : ${n(sc)}. A ridge measures ${cm} cm along the map. How many kilometers is that on the ground?`,r4(cm*sc/100000),tab('The map',[['scale',`1 : ${n(sc)}`],['ridge',`${cm} cm`]]),`${cm} × ${n(sc)} = ${n(cm*sc)} cm = ${r4(cm*sc/100000)} km.`);
 put('scale','A fictional atlas page says "1 cm represents 6.4 km". Two ports are 5 cm apart on the page. How many kilometers apart are they on the ground?',32,tab('The atlas',[['scale','1 cm represents 6.4 km'],['distance','5 cm']]),'5 × 6.4 = 32 km.');
 for(const k of [2,10])put('scale',`A fictional map says "1 cm represents ${k} km." As a ratio that is 1 : ?. Give the number after the colon.`,k*100000,tab('The scale',[['words',`1 cm represents ${k} km`]]),`${k} km = ${n(k*100000)} cm, so the ratio is 1 : ${n(k*100000)}.`);
 for(const [a,b,c] of [[2,10,7.5],[4,5,10]])put('scale',`On a fictional bar scale, ${a} cm on the page equals ${b} km. A road measures ${c} cm on the page. How many kilometers long is the road?`,r4(c*b/a),tab('The bar scale',[['bar',`${a} cm = ${b} km`],['road',`${c} cm`]]),`Each centimeter is ${r4(b/a)} km, so ${c} cm is ${r4(c*b/a)} km.`);
 for(const [sc,pc] of [[100000,200],[50000,50]])put('scale',`A map printed at 1 : ${n(sc)} is photocopied at ${pc}% of its size, so every length on the copy is ${pc/100} times as long. What is the number after the colon in the copy's true ratio?`,sc*100/pc,tab('The copy',[['printed ratio',`1 : ${n(sc)}`],['copy size',`${pc}%`]]),`Lengths scale by ${pc/100}, so the denominator is divided by ${pc/100}: ${n(sc*100/pc)}.`);
 put('scale','A fictional canal is 18 km long. At a scale of 1 : 150,000, how many centimeters long is it on the map?',12,tab('The canal',[['length','18 km'],['scale','1 : 150,000']]),'18 km = 1,800,000 cm; ÷ 150,000 = 12 cm.');
 letters('scale','Choosing a scale',[['1 : 10,000','large scale: a small area in detail'],['1 : 1,000,000','small scale: a large area']],[
  ['Which map would be best for finding one street in a town?','a map at 1 : 10,000',['a map at 1 : 1,000,000','a map at 1 : 30,000,000'],'A 1:10,000 map is large scale: 1 cm shows only 100 m, so streets are visible. 1:1,000,000 shows far more area with much less detail.'],
  ['Why does a bar scale stay correct when a map is enlarged on a copier?','the bar is enlarged by the same amount as the map',['a bar scale is a ratio of numbers','copiers adjust the ground distance'],'A bar scale is drawn on the map, so when the map is enlarged the bar grows by the same amount and still matches. A written ratio would be wrong.']]);
 /* tz */
 put('tz','The Earth turns 360° in 24 hours. How many degrees of longitude does the sun appear to cross each hour?',15,tab('Rotation',[['turn','360°'],['time','24 hours']]),'360 ÷ 24 = 15 degrees per hour.');
 for(const [a,b] of [[30,75],[0,60]])put('tz',`Two fictional towns lie on one parallel, at ${a}° E and ${b}° E. By solar time, how many hours later does noon come at the western town?`,(b-a)/15,tab('The towns',[['first',`${a}° E`],['second',`${b}° E`]]),`${b} - ${a} = ${b-a} degrees; ${b-a} ÷ 15 = ${(b-a)/15} hours.`);
 [['Marlow Bay',-5,'Tessin',2,9],['Quill Harbor',-8,'Orsk Falls',1,20],['Dunmere',3,'Ashby Cove',-4,2]].forEach(([na,oa,nb,ob,h])=>{const fmt=o=>`UTC${o<0?'':'+'}${o}`,ans=(((h+ob-oa)%24)+24)%24;
  put('tz',`${na} keeps ${fmt(oa)} and ${nb} keeps ${fmt(ob)}, both fictional. When it is ${h}:00 in ${na}, what hour is it in ${nb} on the 24-hour clock, from 0 to 23?`,ans,tab('Two fictional places',[[na,fmt(oa)],[nb,fmt(ob)]]),`${nb} is ${ob-oa} hours ahead of ${na}: ${h} + ${ob-oa} = ${h+ob-oa}, which is ${ans} on a 24-hour clock.`);});
 [[-5,1,22,8],[2,-6,9,11]].forEach(([a,b,h,dur])=>{const fmt=o=>`UTC${o<0?'':'+'}${o}`,ans=(((h+dur+b-a)%24)+24)%24;
  put('tz',`A fictional flight leaves Port Hale (${fmt(a)}) at ${h}:00 local time and flies for ${dur} hours to Reed Town (${fmt(b)}). Ignoring daylight saving, what is the local hour of arrival in Reed Town on the 24-hour clock, from 0 to 23?`,ans,tab('The flight',[['leaves',`${h}:00 at ${fmt(a)}`],['flight time',`${dur} hours`],['lands in',fmt(b)]]),`The clock difference is ${b-a} hours: ${h} + ${dur} + ${b-a} = ${h+dur+b-a}, which is ${ans} on a 24-hour clock.`);});
 for(const [lon,hemi] of [[90,'W'],[45,'E']])put('tz',`Ignoring political boundaries, a place at ${lon}° ${hemi} falls in which nominal UTC offset zone? Give the whole number of hours, negative for west of the prime meridian.`,(hemi==='W'?-1:1)*lon/15,tab('The place',[['longitude',`${lon}° ${hemi}`],['rule','15° per hour']]),`${lon} ÷ 15 = ${lon/15} hours${hemi==='W'?', west so negative':''}.`);
 letters('tz','Time zones',[['15°','one hour of longitude'],['UTC','the time standard at 0° longitude']],[
  ['Why do real time zone borders not follow the 15° lines exactly?','they are drawn along national and regional borders for convenience',['the Earth turns unevenly across zones','15° lines were never used anywhere'],'Time zones follow national and regional borders so a country or state can keep one time, rather than splitting along the 15° lines.'],
  ['A traveler flies west across the International Date Line. What happens to the calendar date?','it moves one day ahead',['it moves one day behind','it stays the same'],'Flying west across the International Date Line, you skip ahead one calendar day, for example from Monday to Tuesday.'],
  ['Which statement about time zones is true?','some places use offsets that are not whole hours, such as 5 hours 30 minutes',['every place on Earth uses a whole-hour offset','UTC changes when a country adopts daylight saving'],'Some places use half-hour or other offsets, such as India at UTC plus 5 hours 30 minutes. UTC itself never changes for daylight saving.']]);
 /* loc */
 for(const [d,k] of [['15 Mill Road in the fictional village of Fenwick','absolute'],['about 30 minutes north of the bridge','relative'],['the point at 12° S, 45° W','absolute'],['next door to the bakery','relative'],['the point at 33.5° N, 112.1° W','absolute'],['across the lake from the old fort','relative'],['two hours by train from the capital','relative']])
  put('loc',`Is "${d}" an absolute or a relative location?`,k,tab('A location',[['description',d]],['']),k==='absolute'?'It gives an address or coordinates that fix one place: absolute.':'It describes the place by other places, direction or time: relative.');
 letters('loc','Two kinds of location',[['absolute','coordinates or an address'],['relative','compared with other places']],[
  ['Why does a place have one absolute location but many relative locations?','coordinates are fixed, while relative descriptions depend on which other place you compare with',['relative locations are always more exact','absolute locations change every year'],'Coordinates give one fixed absolute location. Relative location describes a place compared with others, so it changes with what you compare.'],
  ['Which is best for guiding a rescue helicopter to a stranded hiker?','the hiker\'s latitude and longitude',['"near the big pine tree"','"a few hours from the trailhead"'],'Latitude and longitude give an exact position a pilot can fly to. Landmarks and travel times are vague and could fit many places.'],
  ['A new highway cuts a fictional town\'s trip to the capital from 3 hours to 1 hour. What changes?','its relative location, but not its coordinates',['its coordinates, but not its relative location','neither its coordinates nor its relative location'],'The town\'s coordinates do not move, but its connection to the capital improved. That changes its relative location.']]);
 /* contour */
 for(const [a,b,k] of [[100,200,4],[0,100,3],[250,300,4]])put('contour',`On a fictional topographic map, the bold index contours are at ${a} m and ${b} m, with ${k} thinner lines between them. What is the contour interval in meters?`,(b-a)/(k+1),tab('The map',[['index contours',`${a} m and ${b} m`],['lines between',String(k)]]),`There are ${k+1} equal steps from ${a} to ${b}: ${b-a} ÷ ${k+1} = ${(b-a)/(k+1)} m.`);
 for(const [lo,hi,f,txt] of [[340,380,.25,'one quarter'],[600,700,.75,'three quarters'],[120,170,.2,'one fifth']])put('contour',`A fictional spot lies between the ${lo} m and ${hi} m contour lines, ${txt} of the way from the ${lo} m line to the ${hi} m line. Assuming an even slope, what is its elevation in meters?`,r4(lo+f*(hi-lo)),twoContours(lo,hi,f),`${hi} - ${lo} = ${hi-lo}; ${txt} of that is ${r4(f*(hi-lo))}, so ${r4(lo+f*(hi-lo))} m.`);
 put('contour','A fictional park\'s highest point is 842 m and its lowest point is 517 m. What is its relief in meters?',325,tab('The park',[['highest','842 m'],['lowest','517 m']]),'842 - 517 = 325 m.');
 for(const [b,s,i] of [[100,345,20],[0,430,100]])put('contour',`A fictional hill has a base contour at ${b} m and a summit at ${s} m. The contour interval is ${i} m, and a line is drawn at every multiple of the interval above the base, starting with the base itself. How many contour lines are drawn?`,Math.floor((s-b)/i)+1,tab('The hill',[['base',`${b} m`],['summit',`${s} m`],['interval',`${i} m`]]),`Lines fall at ${b}, ${b+i}, ... up to the last one not above ${s}: ${Math.floor((s-b)/i)+1} lines.`);
 letters('contour','Reading contours',[['contour line','joins points of equal elevation'],['closed loops','hill or depression']],[
  ['What does a single contour line connect?','points that have the same elevation',['points the same distance apart','points that share one latitude'],'A contour line joins points of equal elevation, so walking along one you would neither climb nor descend.'],
  ['A set of closed contour loops, each smaller than the last, rises to what?','a hill, with the smallest loop at the top',['a lake, with the smallest loop at the shore','a river valley'],'Closed loops that shrink inward and rise mark a hill or peak, with the smallest loop at the top. Hachure marks show a depression instead.'],
  ['Why do contour lines almost never cross each other?','one place cannot have two elevations',['contour lines are always parallel by definition','the map would not print'],'Each contour stands for one elevation, and one point cannot have two heights, so lines can only touch at a vertical cliff.'],
  ['A V in the contour lines along a stream valley points which way?','uphill, toward the source of the stream',['downhill, toward the sea','across the valley, with no particular direction'],'Where contours cross a stream valley they bend into a V that points uphill, toward the stream\'s source.']]);
 /* grad */
 for(const [cm,sc,e1,e2] of [[4,50000,120,320],[6,25000,300,375],[3,100000,50,230]]){const run=cm*sc/100000,rise=Math.abs(e2-e1);
  put('grad',`Two fictional points are ${cm} cm apart on a map drawn at 1 : ${n(sc)}. One is at ${e1} m and the other at ${e2} m elevation. What is the average gradient, in meters of rise per kilometer of ground distance?`,r4(rise/run),tab('The map',[['scale',`1 : ${n(sc)}`],['map distance',`${cm} cm`],['elevations',`${e1} m and ${e2} m`]]),`Run: ${cm} × ${n(sc)} ÷ 100,000 = ${run} km. Rise: ${rise} m. ${rise} ÷ ${run} = ${r4(rise/run)} m per km.`);}
 for(const [r,d] of [[30,600],[45,300],[90,1200]])put('grad',`A fictional trail climbs ${r} m over a horizontal distance of ${d} m. What is its percent grade, rise divided by run times 100?`,r4(r*100/d),tab('The trail',[['rise',`${r} m`],['run',`${d} m`]]),`${r} ÷ ${d} × 100 = ${r4(r*100/d)}%.`);
 put('grad','Fictional slope P rises 90 m in 1.5 km; fictional slope Q rises 120 m in 3 km. Which is steeper: P or Q?','P',tab('The slopes',[['P','90 m in 1.5 km'],['Q','120 m in 3 km']]),'P is 60 m per km; Q is 40 m per km, so P is steeper.');
 put('grad','A fictional hiker crosses contour lines at 300, 320, 340, 360, 340 and 320 m, in that order. How many meters of uphill climbing did she do (count only the rising parts)?',60,tab('The walk',[['lines crossed','300, 320, 340, 360, 340, 320 m']]),'300 to 360 is 60 m up; the rest is downhill.');
 put('grad','A fictional hiker crosses contour lines at 500, 520, 540, 520, 500 and 480 m, in that order. What is the net change in elevation from the first line to the last, in meters? Count a drop as a negative number.',-20,tab('The walk',[['lines crossed','500, 520, 540, 520, 500, 480 m']]),'480 - 500 = -20 m.');
 letters('grad','Slopes on maps',[['close lines','steep'],['far lines','gentle']],[
  ['On a topographic map, which way do streams flow relative to the contour lines?','downhill, crossing the lines at right angles',['along one contour line at constant elevation','uphill, against the slope'],'Water flows downhill, the steepest way, which crosses contour lines at right angles, from higher contours to lower ones.'],
  ['Two maps share a scale and a contour interval. Which slope is steeper?','the one whose contour lines are closer together',['the one whose contour lines are farther apart','the one with more labels'],'Closer contour lines mean elevation changes over a shorter distance, so the slope is steeper.'],
  ['A profile (cross-section) drawn with a stretched vertical scale does what?','makes slopes look steeper than they are',['makes slopes look gentler than they are','has no effect on how slopes look'],'Stretching the vertical scale, called vertical exaggeration, makes hills look taller and slopes steeper than they really are.']]);
 /* bearing */
 for(const dir of ['south-east','south-west','east-southeast','north-northwest'])put('bearing',`Compass bearings run clockwise from north through 0° to 360°. What is the bearing of ${dir}, in degrees?`,{'south-east':135,'south-west':225,'north-west':315,west:270,'east-southeast':112.5,'north-northwest':337.5}[dir],tab('The direction',[['direction',dir]]),`North is 0°, east 90°, south 180°, west 270°; ${dir} lies between them at ${{'south-east':135,'south-west':225,'north-west':315,west:270,'east-southeast':112.5,'north-northwest':337.5}[dir]}°.`);
 for(const b of [70,250])put('bearing',`You walk on a bearing of ${b}° from camp. What is the bearing for the walk straight back to camp?`,(b+180)%360,tab('The walk',[['outward bearing',`${b}°`]]),`${b} ${b<180?'+':'-'} 180 = ${(b+180)%360}°.`);
 for(const [dx,dy] of [[5,5],[3,4],[4,-4],[-5,12]]){const deg=Math.round((Math.atan2(dx,dy)*180/Math.PI+360)%360),ew=dx>0?'east':'west',ns=dy>0?'north':'south';
  put('bearing',`On a fictional grid map, Point B is ${Math.abs(dx)} km ${ew} and ${Math.abs(dy)} km ${ns} of Point A. What is the bearing from A to B, to the nearest degree?`,deg,bearingPic(dx,dy),`The angle clockwise from north to the line AB is about ${deg}°.`);}
 for(const [dec,t] of [[8,100],[8,5]])put('bearing',`At a fictional site the compass needle points ${dec}° east of true north. Magnetic bearing = true bearing - ${dec}°, wrapping into 0 to 359. A target lies on a true bearing of ${t}°. What magnetic bearing should the compass show?`,(t-dec+360)%360,tab('Declination',[['declination',`${dec}° east`],['true bearing',`${t}°`]]),`${t} - ${dec} = ${t-dec}${t-dec<0?`, which wraps to ${(t-dec+360)%360}`:''}°.`);
 for(const [a,t,side] of [[40,90,'right']])put('bearing',`You are heading on a bearing of ${a}° and turn ${t}° to the ${side}. What is your new bearing?`,((side==='right'?a+t:a-t)+360)%360,tab('The turn',[['heading',`${a}°`],['turn',`${t}° ${side}`]]),`A right turn adds and a left turn subtracts: ${side==='right'?a+t:a-t}${side==='left'&&a-t<0?`, which wraps to ${a-t+360}`:''}°.`);
 /* gps */
 for(const t of [0.068,0.07,0.075])put('gps',`A fictional GPS satellite signal takes ${t} seconds to reach a receiver. Using 300,000 km/s for the speed of the signal, how many kilometers away is the satellite?`,r4(t*300000),tab('The signal',[['delay',`${t} s`],['speed','300,000 km/s']]),`${t} × 300,000 = ${n(r4(t*300000))} km.`);
 for(const d of [24000,22500])put('gps',`A fictional satellite is ${n(d)} km from a receiver. Using 300,000 km/s, how many seconds does its signal take to arrive?`,r4(d/300000),tab('The satellite',[['distance',`${n(d)} km`],['speed','300,000 km/s']]),`${n(d)} ÷ 300,000 = ${r4(d/300000)} s.`);
 [[9,28,'x',15,17,10,25],[4,12,'y',12,15,13,9],[14,12,'x',5,13,15,5],[21,28,'y',8,17,10,25]].forEach(([bx,cy,ask,v,dA,dB,dC])=>put('gps',`On a fictional flat map, beacon A is at (0, 0), beacon B at (${bx}, 0) and beacon C at (0, ${cy}), in kilometers. A receiver finds it is ${dA} km from A, ${dB} km from B and ${dC} km from C. Its x and y are both positive. What is its ${ask} coordinate in kilometers?`,v,tab('Beacons',[['A','(0, 0), '+dA+' km'],['B',`(${bx}, 0), ${dB} km`],['C',`(0, ${cy}), ${dC} km`]]),`Only one positive point is ${dA} km from A, ${dB} km from B and ${dC} km from C: its ${ask} coordinate is ${v}.`));
 letters('gps','GPS',[['signal','satellite position and time sent'],['fix','from at least four satellites']],[
  ['How many satellites does a GPS receiver need for a full three-dimensional position and a correct clock?','at least four',['only one','exactly two'],'Three satellites fix position in three dimensions, and a fourth corrects the receiver\'s clock error, so at least four are needed.'],
  ['If a receiver knows only its distance from one satellite, where can it be?','anywhere on a sphere around that satellite',['at one exact point','on a straight line toward the satellite'],'Knowing only the distance to one satellite places you anywhere on a sphere of that radius around it. More satellites narrow it down.'],
  ['What does a phone\'s GPS receiver do with satellite signals?','it only receives them to work out its own position',['it sends its position up to each satellite','it bounces them back to find the satellite\'s height'],'A GPS receiver only listens. It times signals from several satellites and calculates its own position without sending anything back.'],
  ['What does GNSS mean?','Global Navigation Satellite System, the general name that includes GPS and other systems',['a type of map projection','the network of ground stations that print maps'],'GNSS, Global Navigation Satellite System, is the general name for satellite positioning systems, including GPS, Galileo, GLONASS and BeiDou.']],1);
 /* gis */
 for(const [f,k] of [['a water well','point'],['a river drawn as a thin feature','line'],['a lake','polygon'],['a bus stop','point'],['a railway','line'],['a county boundary enclosing an area','polygon']])
  put('gis',`In a vector GIS, which kind of feature is usually used to store ${f}: point, line or polygon?`,k,tab('A feature',[['feature',f]],['']),k==='point'?'A single location is stored as a point.':k==='line'?'A feature that is long and narrow is stored as a line.':'A feature that encloses an area is stored as a polygon.');
 letters('gis','GIS',[['vector','points, lines, polygons'],['raster','grid of cells']],[
  ['What is a GIS layer?','one set of data about a place, such as roads or soils, that shares coordinates with other layers',['a printed sheet laid over a paper map','a type of cloud above a map'],'A GIS layer holds one kind of data, like roads or soils, tied to shared coordinates so layers can be stacked and compared.'],
  ['What does overlaying a flood-zone layer on a schools layer help a planner find?','which schools lie inside the flood zone',['the shortest bus route between schools','the elevation of every school'],'Overlaying the layers shows where schools and the flood zone overlap, so the planner can see which schools are at risk.'],
  ['What does a buffer around a river in a GIS show?','all the area within a set distance of the river',['the river\'s source','the river\'s age'],'A buffer marks all the area within a set distance of a feature, such as every place within 100 m of a river.'],
  ['What is geocoding?','turning an address into coordinates that can be mapped',['turning coordinates into a time zone','removing errors from a satellite image'],'Geocoding turns an address into map coordinates, so it can be placed as a point in a GIS.'],
  ['Which describes a raster layer?','a grid of cells, each holding a value',['a list of points joined by lines','a table with no locations'],'A raster is a grid of cells, each holding a value, like a pixel in a photo. A set of points and lines is vector data.']]);
 /* rs */
 for(const [p,k] of [[30,3],[10,2],[20,1]])put('rs',`A fictional satellite image has pixels ${p} m on a side. How many pixels cover a square ${k} km on a side?`,(k*1000/p)**2,tab('The image',[['pixel',`${p} m`],['area',`${k} km by ${k} km`]]),`${k} km = ${k*1000} m; ${k*1000} ÷ ${p} = ${k*1000/p} pixels per side, and ${k*1000/p} squared is ${n((k*1000/p)**2)}.`);
 for(const p of [30,250])put('rs',`Each pixel of a fictional image covers a ${p} m by ${p} m square on the ground. How many square meters does one pixel cover?`,p*p,tab('A pixel',[['side',`${p} m`]]),`${p} × ${p} = ${n(p*p)} square meters.`);
 for(const [s,k] of [['A camera that records sunlight reflected from forests','passive'],['Radar that sends out microwave pulses and times their echoes','active'],['A laser scanner on an aircraft that fires pulses and times the returns to measure tree height','active'],['A satellite sensor that records heat given off by the ground','passive']])
  put('rs',`${s}. Is this a passive or an active remote sensor?`,k,tab('A sensor',[['sensor',s]],['']),k==='active'?'It sends out its own energy and records the return: active.':'It records energy that comes from the sun or the surface: passive.');
 put('rs','A fictional satellite passes over the same spot every 16 days. About how many complete passes does it make over that spot in 365 days?',22,tab('Revisits',[['pass every','16 days'],['period','365 days']]),'365 ÷ 16 = 22.8, so 22 complete passes.');
 letters('rs','Remote sensing',[['pixel','one cell of an image'],['resolution','ground size of a pixel']],[
  ['What does spatial resolution describe in a satellite image?','how much ground one pixel covers, so smaller pixels show finer detail',['how many years of images exist','how far the satellite is from the sun'],'Spatial resolution is how much ground one pixel covers. Smaller pixels mean finer detail, such as 1 m pixels showing cars.'],
  ['Which is a strength of remote sensing?','it can record large or dangerous areas repeatedly without anyone going there',['it replaces every need for fieldwork','it shows what people think about a place'],'Satellites can image huge, remote or dangerous areas again and again without sending people. Fieldwork is still needed to check results.']]);
 /* mental */
 for(const [s,k] of [['A tall clock tower that people use to say where they are','landmark'],['A wide river that divides the east and west sides of a city','edge'],['A neighborhood known for its markets that people think of as one area','district'],['The main square where several bus routes meet','node'],['Main Street, along which people drive and walk across the city','path']])
  put('mental',`In Kevin Lynch's scheme for how people picture a city, which element is this: ${s}? Choose path, edge, district, node or landmark.`,k,tab('A city element',[['example',s]],['']),`That is a ${k}.`);
 letters('mental','Mental maps',[['mental map','a personal picture of places'],['Lynch','paths, edges, districts, nodes, landmarks']],[
  ['What is a mental map?','the picture of places a person carries in mind, shaped by experience',['an exact map stored in a GIS','a map drawn only by surveyors'],'A mental map is the picture of places a person carries in mind, based on experience, so it is not to scale.'],
  ['How are familiar areas usually drawn on a sketch map?','larger and more detailed than distant areas',['smaller and less detailed than distant areas','exactly to scale'],'People know familiar areas best, so on sketch maps they draw them bigger and more detailed than distant places.'],
  ['Why might two people who live in one town draw different mental maps of it?','they use different places and routes, so they know different parts well',['one of them is always wrong about the town','mental maps are identical for everyone'],'Mental maps come from experience. Two people who use different routes and places will know different parts of town well.'],
  ['Why do geographers study mental maps?','to learn how people see places, which affects choices such as where they shop or travel',['to correct every person\'s map to scale','to replace satellite images'],'How people picture places affects their choices, such as where they shop, travel or feel safe, so mental maps help explain behavior.'],
  ['Which can shape a person\'s mental map of a distant country?','news, stories and pictures, as well as travel',['only travel there','only the national flag'],'News, stories, films and pictures shape how people imagine distant places, even places they have never visited.']]);
 /* spatial */
 for(const [p,a] of [[24000,8],[45000,90]])put('spatial',`A fictional district has ${n(p)} people living on ${a} square kilometers. What is its population density in people per square kilometer?`,r4(p/a),tab('The district',[['people',n(p)],['area',`${a} km²`]]),`${n(p)} ÷ ${a} = ${r4(p/a)} people per km².`);
 for(const [d,p] of [[120,36000],[40,10000]])put('spatial',`A fictional county has a density of ${d} people per square kilometer and ${n(p)} people. How many square kilometers does it cover?`,p/d,tab('The county',[['density',`${d} per km²`],['people',n(p)]]),`${n(p)} ÷ ${d} = ${p/d} km².`);
 for(const t of [5,6])put('spatial',`A fictional region has ${t} towns. If every pair of towns has its own direct road, how many roads are there?`,t*(t-1)/2,tab('The network',[['towns',String(t)]]),`${t} × ${t-1} ÷ 2 = ${t*(t-1)/2} roads.`);
 for(const [s,k] of [['Ten farmhouses stand in a tight group near a spring, with no others for 20 km.','clustered'],['Villages are spaced about evenly, 10 km apart, across a plain.','dispersed'],['Shops stand one after another along a single highway.','linear']])
  put('spatial',`${s} Is this pattern clustered, dispersed or linear?`,k,tab('A pattern',[['case',s]],['']),`That arrangement is ${k}.`);
 letters('spatial','Describing places',[['density','a count per area'],['connectivity','links between places']],[
  ['Two fictional towns are 50 km apart. One trip crosses a mountain pass and takes 4 hours; another trip over a plain takes 40 minutes. What differs?','the relative (time) distance, not the straight-line distance',['the absolute distance, which is greater by the mountain route','nothing, because both trips are 50 km'],'Both towns are 50 km apart in a straight line, but the mountain trip takes far longer. The time distance differs, not the absolute distance.'],
  ['What does accessibility describe?','how easily people can reach a place, which depends on travel time and cost',['how high a place is above sea level','how many people were born there'],'Accessibility is how easily people can reach a place, which depends on distance, travel time, cost and connections.'],
  ['Why might adding one road make a network better connected?','it adds a link between towns that were not directly joined',['it removes a town from the network','it changes the scale of the map'],'A new road can link two towns directly, adding a connection, so the network becomes better connected.']],2);
}};
